//! Sealed history records (ADR-0017): the plaintext messages of a chat, encrypted for the device's own storage.
//!
//! One [`HistoryCipher`] holds one random 32-byte **history key** (generated by the app, wrapped by the platform key
//! like the snapshot key, ADR-0011) and the canonical origin. Two sub-keys are derived from it with HKDF-Expand
//! (SHA-256), so one purpose can never be confused with the other:
//!
//! ```text
//! seal_key = HKDF-Expand(history_key, "gifitup history seal v1", 32)
//! name_key = HKDF-Expand(history_key, "gifitup history name v1", 32)
//! ```
//!
//! **Record names** are what the store sees of a record: `HMAC-SHA-256(name_key, kind ‖ u32-BE len ‖ group id [‖ u32-BE
//! len ‖ message reference])` with `kind` `g` (the group's folder), `m` (a message) or `r` (the read mark). Without the
//! key they say nothing about the group id or the message reference, and the store can't link a record to the server's
//! ciphertext.
//!
//! **Sealed record**: `"GIUH" ‖ version(1) ‖ nonce[12] ‖ AES-256-GCM(padded)`, with the header and the context as
//! associated data: `header ‖ "gifitup history v1" ‖ 0x00 ‖ origin ‖ 0x00 ‖ record name`, so a record can't move to
//! another name, group or origin, and a version can't be swapped. The AEAD is the OpenMLS crypto provider's (the same as
//! the snapshot, nothing hand-rolled) with a fresh random 96-bit nonce per seal. `padded` is `u32-BE length ‖ plaintext
//! ‖ zeros` up to a multiple of [`BUCKET`], so the size of a record only tells which 1 KiB bucket the message is in.
//! Random-nonce bound: every seal counts (a rewrite for a new delivery state too), 2^32 under one key (NIST SP 800-38D);
//! no history can come near it and no counter is kept.
//!
//! The sizes are checked before anything is decrypted, and the inner layout is only read after the tag verified.

use openmls_rust_crypto::RustCrypto;
use openmls_traits::crypto::OpenMlsCrypto;
use openmls_traits::random::OpenMlsRand;
use openmls_traits::types::{AeadType, CryptoError, HashType};
use zeroize::Zeroizing;

use crate::error::ErrorCode;
use crate::snapshot::{KEY_LEN, take_key};

const MAGIC: &[u8; 4] = b"GIUH";
const VERSION: u8 = 1;
const NONCE_LEN: usize = 12;
const TAG_LEN: usize = 16;
const HEADER_LEN: usize = 4 + 1 + NONCE_LEN;
/// Plaintext sizes are rounded up to a multiple of this.
pub(crate) const BUCKET: usize = 1024;
/// The most a record may hold: four buckets minus the 4-byte length (a message needs under 1 KiB).
pub(crate) const MAX_PLAINTEXT: usize = 4 * BUCKET - 4;
/// Length of a record name.
pub(crate) const NAME_LEN: usize = 32;
const MAX_ORIGIN_BYTES: usize = 256;
const MAX_ID_BYTES: usize = 128;

const LABEL_SEAL: &[u8] = b"gifitup history seal v1";
const LABEL_NAME: &[u8] = b"gifitup history name v1";
const AAD_LABEL: &[u8] = b"gifitup history v1";

type SubKey = Zeroizing<[u8; KEY_LEN]>;

/// Seals and opens history records. Secret values are wiped when it is dropped.
pub(crate) struct HistoryCipher {
    crypto: RustCrypto,
    seal_key: SubKey,
    name_key: SubKey,
    origin: Vec<u8>,
}

impl HistoryCipher {
    /// `history_key` is copied and the caller's buffer wiped; `origin` is the canonical origin text of the account.
    pub(crate) fn new(history_key: Vec<u8>, origin: &str) -> Result<Self, ErrorCode> {
        let key = take_key(history_key)?;
        if origin.is_empty() || origin.len() > MAX_ORIGIN_BYTES {
            return Err(ErrorCode::InvalidInput);
        }
        let crypto = RustCrypto::default();
        let seal_key = derive(&crypto, key.as_slice(), LABEL_SEAL)?;
        let name_key = derive(&crypto, key.as_slice(), LABEL_NAME)?;
        Ok(Self {
            crypto,
            seal_key,
            name_key,
            origin: origin.as_bytes().to_vec(),
        })
    }

    /// The name of the group's folder.
    pub(crate) fn group_name(&self, group_id: &[u8]) -> Result<[u8; NAME_LEN], ErrorCode> {
        self.name(b'g', group_id, None)
    }

    /// The name of one message of a group.
    pub(crate) fn message_name(
        &self,
        group_id: &[u8],
        reference: &[u8],
    ) -> Result<[u8; NAME_LEN], ErrorCode> {
        self.name(b'm', group_id, Some(reference))
    }

    /// The name of a group's read mark.
    pub(crate) fn read_mark_name(&self, group_id: &[u8]) -> Result<[u8; NAME_LEN], ErrorCode> {
        self.name(b'r', group_id, None)
    }

    fn name(
        &self,
        kind: u8,
        group_id: &[u8],
        reference: Option<&[u8]>,
    ) -> Result<[u8; NAME_LEN], ErrorCode> {
        let too_long = |id: &[u8]| id.is_empty() || id.len() > MAX_ID_BYTES;
        if too_long(group_id) || reference.is_some_and(too_long) {
            return Err(ErrorCode::InvalidInput);
        }
        let mut data = vec![kind];
        for part in std::iter::once(group_id).chain(reference) {
            data.extend_from_slice(
                &u32::try_from(part.len())
                    .map_err(|_| ErrorCode::Internal)?
                    .to_be_bytes(),
            );
            data.extend_from_slice(part);
        }
        let mac = self
            .crypto
            .hmac(HashType::Sha2_256, self.name_key.as_slice(), &data)
            .map_err(|_| ErrorCode::Internal)?;
        <[u8; NAME_LEN]>::try_from(mac.as_slice()).map_err(|_| ErrorCode::Internal)
    }

    /// Seals `plaintext` for the record called `name` (a name this cipher made).
    pub(crate) fn seal(&self, name: &[u8], plaintext: &[u8]) -> Result<Vec<u8>, ErrorCode> {
        if name.len() != NAME_LEN || plaintext.len() > MAX_PLAINTEXT {
            return Err(ErrorCode::HistoryInvalid);
        }
        let padded = pad(plaintext)?;
        let nonce: [u8; NONCE_LEN] = self
            .crypto
            .random_array()
            .map_err(|_| ErrorCode::Internal)?;
        let mut out = header(&nonce);
        let sealed = self
            .crypto
            .aead_encrypt(
                AeadType::Aes256Gcm,
                self.seal_key.as_slice(),
                &padded,
                &nonce,
                &self.aad(&out, name),
            )
            .map_err(|_| ErrorCode::Internal)?;
        out.extend_from_slice(&sealed);
        Ok(out)
    }

    /// Opens a sealed record that was made for `name`. A wrong key, name or origin, or a changed byte, is
    /// `HistoryAuth`; a size or header that no seal makes is `HistoryInvalid`, before anything is decrypted.
    pub(crate) fn open(&self, name: &[u8], sealed: &[u8]) -> Result<Vec<u8>, ErrorCode> {
        let body = sealed.len().checked_sub(HEADER_LEN + TAG_LEN);
        let valid_size = body.is_some_and(|n| n > 0 && n % BUCKET == 0 && n <= MAX_PLAINTEXT + 4);
        if name.len() != NAME_LEN || !valid_size || sealed[..4] != MAGIC[..] || sealed[4] != VERSION
        {
            return Err(ErrorCode::HistoryInvalid);
        }
        let (head, ct) = sealed.split_at(HEADER_LEN);
        let nonce: [u8; NONCE_LEN] = head[5..]
            .try_into()
            .map_err(|_| ErrorCode::HistoryInvalid)?;
        let padded = self
            .crypto
            .aead_decrypt(
                AeadType::Aes256Gcm,
                self.seal_key.as_slice(),
                ct,
                &nonce,
                &self.aad(head, name),
            )
            .map(Zeroizing::new)
            .map_err(|e| match e {
                CryptoError::AeadDecryptionError => ErrorCode::HistoryAuth,
                _ => ErrorCode::Internal,
            })?;
        unpad(&padded)
    }

    fn aad(&self, head: &[u8], name: &[u8]) -> Vec<u8> {
        let mut aad =
            Vec::with_capacity(head.len() + AAD_LABEL.len() + self.origin.len() + name.len() + 2);
        aad.extend_from_slice(head);
        aad.extend_from_slice(AAD_LABEL);
        aad.push(0);
        aad.extend_from_slice(&self.origin);
        aad.push(0);
        aad.extend_from_slice(name);
        aad
    }
}

fn derive(crypto: &RustCrypto, key: &[u8], label: &[u8]) -> Result<SubKey, ErrorCode> {
    let okm = crypto
        .hkdf_expand(HashType::Sha2_256, key, label, KEY_LEN)
        .map_err(|_| ErrorCode::Internal)?;
    <[u8; KEY_LEN]>::try_from(okm.as_slice())
        .map(Zeroizing::new)
        .map_err(|_| ErrorCode::Internal)
}

fn header(nonce: &[u8; NONCE_LEN]) -> Vec<u8> {
    let mut head = Vec::with_capacity(HEADER_LEN);
    head.extend_from_slice(MAGIC);
    head.push(VERSION);
    head.extend_from_slice(nonce);
    head
}

/// `u32-BE length ‖ plaintext ‖ zeros`, up to a multiple of [`BUCKET`].
fn pad(plaintext: &[u8]) -> Result<Zeroizing<Vec<u8>>, ErrorCode> {
    let len = u32::try_from(plaintext.len()).map_err(|_| ErrorCode::HistoryInvalid)?;
    let size = (4 + plaintext.len()).div_ceil(BUCKET) * BUCKET;
    let mut out = Zeroizing::new(Vec::with_capacity(size));
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(plaintext);
    out.resize(size, 0);
    Ok(out)
}

/// Reads the length, then checks that the rest is zeros: a record that no seal made is `HistoryInvalid`.
fn unpad(padded: &[u8]) -> Result<Vec<u8>, ErrorCode> {
    let (len, rest) = padded
        .split_at_checked(4)
        .ok_or(ErrorCode::HistoryInvalid)?;
    let len = usize::try_from(u32::from_be_bytes(
        len.try_into().map_err(|_| ErrorCode::HistoryInvalid)?,
    ))
    .map_err(|_| ErrorCode::HistoryInvalid)?;
    let (plaintext, zeros) = rest
        .split_at_checked(len)
        .ok_or(ErrorCode::HistoryInvalid)?;
    if zeros.iter().any(|b| *b != 0) {
        return Err(ErrorCode::HistoryInvalid);
    }
    Ok(plaintext.to_vec())
}

#[cfg(test)]
mod tests {
    use super::*;

    const ORIGIN: &str = "https://chat.example.test";

    fn key(byte: u8) -> Vec<u8> {
        vec![byte; KEY_LEN]
    }

    fn cipher() -> HistoryCipher {
        HistoryCipher::new(key(7), ORIGIN).unwrap()
    }

    fn hex(bytes: &[u8]) -> String {
        bytes.iter().map(|b| format!("{b:02x}")).collect()
    }

    /// Computed outside this crate (Python `hmac`/`hashlib`, HKDF-Expand written out from RFC 5869) for the key
    /// `0, 1, 2, ..., 31`, group id `[1; 16]`, reference `[2; 32]`: a wrong label, kind byte, length prefix or sub-key
    /// would not agree with itself here.
    #[test]
    fn record_names_agree_with_an_independent_computation() {
        let key: Vec<u8> = (0..32).collect();
        let cipher = HistoryCipher::new(key, ORIGIN).unwrap();
        let group = [1u8; 16];
        let reference = [2u8; 32];
        assert_eq!(
            hex(&cipher.group_name(&group).unwrap()),
            "7b3fc1e676bdfbc721f9b2e1c8195282c2d98cae43597c5bc08af81221236188"
        );
        assert_eq!(
            hex(&cipher.message_name(&group, &reference).unwrap()),
            "e2e843b3666a25de49acc6853a3b15421cc256a5d5e619e822536b91387fc4ba"
        );
        assert_eq!(
            hex(&cipher.read_mark_name(&group).unwrap()),
            "709bd904c4485141b648ebe8b5312bd7b8cdad35e84d80ffad906077354dbcfb"
        );
    }

    #[test]
    fn names_depend_on_the_key_the_kind_the_group_and_the_reference() {
        let a = cipher();
        let b = HistoryCipher::new(key(8), ORIGIN).unwrap();
        let group = [1u8; 16];
        let reference = [2u8; 32];
        let name = a.message_name(&group, &reference).unwrap();
        assert_eq!(name, a.message_name(&group, &reference).unwrap());
        assert_ne!(name, b.message_name(&group, &reference).unwrap());
        assert_ne!(name, a.message_name(&[3u8; 16], &reference).unwrap());
        assert_ne!(name, a.message_name(&group, &[3u8; 32]).unwrap());
        assert_ne!(
            a.group_name(&group).unwrap(),
            a.read_mark_name(&group).unwrap()
        );
        // The length prefix keeps (group, reference) pairs with the same concatenation apart.
        assert_ne!(
            a.message_name(&[1, 2], &[3]).unwrap(),
            a.message_name(&[1], &[2, 3]).unwrap()
        );
    }

    #[test]
    fn names_refuse_empty_and_oversize_ids() {
        let c = cipher();
        assert_eq!(c.group_name(&[]), Err(ErrorCode::InvalidInput));
        assert_eq!(
            c.group_name(&[0; MAX_ID_BYTES + 1]),
            Err(ErrorCode::InvalidInput)
        );
        assert_eq!(c.message_name(&[1], &[]), Err(ErrorCode::InvalidInput));
        assert!(
            c.message_name(&[1; MAX_ID_BYTES], &[2; MAX_ID_BYTES])
                .is_ok()
        );
    }

    #[test]
    fn a_sealed_record_opens_to_what_was_sealed() {
        let c = cipher();
        let name = c.message_name(&[1; 16], &[2; 32]).unwrap();
        for len in [0usize, 1, 900, 1020, 1021, 2000, MAX_PLAINTEXT] {
            let plaintext: Vec<u8> = (0..len).map(|i| (i % 251) as u8).collect();
            let sealed = c.seal(&name, &plaintext).unwrap();
            assert_eq!(c.open(&name, &sealed).unwrap(), plaintext, "length {len}");
        }
    }

    #[test]
    fn the_size_of_a_record_only_tells_the_bucket() {
        let c = cipher();
        let name = c.message_name(&[1; 16], &[2; 32]).unwrap();
        let small = c.seal(&name, b"hi").unwrap();
        let larger = c.seal(&name, &[b'x'; 1000]).unwrap();
        assert_eq!(small.len(), larger.len());
        assert_eq!(small.len(), HEADER_LEN + BUCKET + TAG_LEN);
        assert_eq!(
            c.seal(&name, &[b'x'; 1021]).unwrap().len(),
            HEADER_LEN + 2 * BUCKET + TAG_LEN
        );
    }

    #[test]
    fn every_seal_uses_a_new_nonce() {
        let c = cipher();
        let name = c.group_name(&[1; 16]).unwrap();
        let first = c.seal(&name, b"same").unwrap();
        let second = c.seal(&name, b"same").unwrap();
        assert_ne!(first[5..HEADER_LEN], second[5..HEADER_LEN]);
        assert_ne!(first, second);
    }

    #[test]
    fn another_key_name_or_origin_does_not_open_it() {
        let c = cipher();
        let name = c.message_name(&[1; 16], &[2; 32]).unwrap();
        let sealed = c.seal(&name, b"secret").unwrap();
        let other_key = HistoryCipher::new(key(8), ORIGIN).unwrap();
        assert_eq!(other_key.open(&name, &sealed), Err(ErrorCode::HistoryAuth));
        let other_origin = HistoryCipher::new(key(7), "https://other.example.test").unwrap();
        assert_eq!(
            other_origin.open(&name, &sealed),
            Err(ErrorCode::HistoryAuth)
        );
        let other_name = c.message_name(&[1; 16], &[3; 32]).unwrap();
        assert_eq!(c.open(&other_name, &sealed), Err(ErrorCode::HistoryAuth));
    }

    #[test]
    fn any_changed_byte_is_refused() {
        let c = cipher();
        let name = c.message_name(&[1; 16], &[2; 32]).unwrap();
        let sealed = c.seal(&name, b"secret").unwrap();
        for at in 0..sealed.len() {
            let mut bad = sealed.clone();
            bad[at] ^= 0x01;
            let result = c.open(&name, &bad);
            let expected = if at < 5 {
                ErrorCode::HistoryInvalid
            } else {
                ErrorCode::HistoryAuth
            };
            assert_eq!(result, Err(expected), "byte {at}");
        }
    }

    #[test]
    fn sizes_no_seal_makes_are_invalid_before_decryption() {
        let c = cipher();
        let name = c.group_name(&[1; 16]).unwrap();
        let sealed = c.seal(&name, b"x").unwrap();
        assert_eq!(c.open(&name, &[]), Err(ErrorCode::HistoryInvalid));
        assert_eq!(
            c.open(&name, &sealed[..HEADER_LEN]),
            Err(ErrorCode::HistoryInvalid)
        );
        assert_eq!(
            c.open(&name, &sealed[..sealed.len() - 1]),
            Err(ErrorCode::HistoryInvalid)
        );
        let mut longer = sealed.clone();
        longer.push(0);
        assert_eq!(c.open(&name, &longer), Err(ErrorCode::HistoryInvalid));
        assert_eq!(
            c.open(&name, &vec![0u8; 1 << 20]),
            Err(ErrorCode::HistoryInvalid)
        );
        assert_eq!(c.open(&name[..31], &sealed), Err(ErrorCode::HistoryInvalid));
    }

    #[test]
    fn oversize_plaintext_and_bad_names_are_refused_when_sealing() {
        let c = cipher();
        let name = c.group_name(&[1; 16]).unwrap();
        assert_eq!(
            c.seal(&name, &vec![0; MAX_PLAINTEXT + 1]),
            Err(ErrorCode::HistoryInvalid)
        );
        assert_eq!(c.seal(&name[..31], b"x"), Err(ErrorCode::HistoryInvalid));
    }

    /// A record with a right tag and a wrong inner layout: sealed by hand under the cipher's own key.
    fn sealed_by_hand(c: &HistoryCipher, name: &[u8], body: &[u8]) -> Vec<u8> {
        let nonce = [9u8; NONCE_LEN];
        let mut out = header(&nonce);
        let sealed = c
            .crypto
            .aead_encrypt(
                AeadType::Aes256Gcm,
                c.seal_key.as_slice(),
                body,
                &nonce,
                &c.aad(&out, name),
            )
            .unwrap();
        out.extend_from_slice(&sealed);
        out
    }

    #[test]
    fn a_padding_that_is_not_zeros_or_a_length_past_the_end_is_invalid() {
        let c = cipher();
        let name = c.group_name(&[1; 16]).unwrap();
        let mut dirty = [&5u32.to_be_bytes()[..], b"abcde"].concat();
        dirty.resize(BUCKET, 0);
        dirty[BUCKET - 1] = 1;
        assert_eq!(
            c.open(&name, &sealed_by_hand(&c, &name, &dirty)),
            Err(ErrorCode::HistoryInvalid)
        );
        let mut too_long = 2000u32.to_be_bytes().to_vec();
        too_long.resize(BUCKET, 0);
        assert_eq!(
            c.open(&name, &sealed_by_hand(&c, &name, &too_long)),
            Err(ErrorCode::HistoryInvalid)
        );
        // The same layout with clean padding does open.
        let mut clean = [&5u32.to_be_bytes()[..], b"abcde"].concat();
        clean.resize(BUCKET, 0);
        assert_eq!(
            c.open(&name, &sealed_by_hand(&c, &name, &clean)).unwrap(),
            b"abcde"
        );
    }

    #[test]
    fn keys_and_origins_of_the_wrong_size_are_refused() {
        assert!(HistoryCipher::new(vec![0; 31], ORIGIN).is_err());
        assert!(HistoryCipher::new(vec![0; 33], ORIGIN).is_err());
        assert!(HistoryCipher::new(key(1), "").is_err());
        assert!(HistoryCipher::new(key(1), &"x".repeat(MAX_ORIGIN_BYTES + 1)).is_err());
    }
}
